"""Algorithm B: alphabet-universal channel-dilution verifier."""

from __future__ import annotations

from fractions import Fraction as F
from typing import Dict, Tuple


def channel_sum_counts(q: int, m: int) -> Dict[int, int]:
    """Multiplicity of every value of a sum of m i.i.d. uniform digits from {0,...,q-1}.

    Grouping by value turns the q^m raw configurations into at most m(q-1)+1 distinct
    values, so the enumeration is O(m^2 q) instead of O(q^m) while remaining exact and
    exhaustive.
    """
    counts: Dict[int, int] = {0: 1}
    for _ in range(m):
        nxt: Dict[int, int] = {}
        for w, c in counts.items():
            for d in range(q):
                nxt[w + d] = nxt.get(w + d, 0) + c
        counts = nxt
    return counts


def qary_channel_rho_sq(q: int, a: F, m: int) -> F:
    """Exact rho^2 of the q-ary channel sample {(d, a d + w)} with multiplicities.

    The predictor is one uniform q-ary digit; the response carries that digit with weight a
    and adds the sum of m further independent uniform q-ary digits.
    """
    counts = channel_sum_counts(q, m)
    n = 0
    sx = sy = sxx = syy = sxy = F(0)
    for d in range(q):
        for w, c in counts.items():
            x, y = F(d), a * d + w
            n += c
            sx += c * x
            sy += c * y
            sxx += c * x * x
            syy += c * y * y
            sxy += c * x * y
    cov = n * sxy - sx * sy
    return cov * cov / ((n * sxx - sx * sx) * (n * syy - sy * sy))


def verify_alphabet_universality(a: F, m: int, alphabets: Tuple[int, ...] = (2, 3, 4, 5, 8, 16)) -> bool:
    """Check rho^2 = a^2/(a^2+m) for every alphabet size, exactly."""
    target = a * a / (a * a + m)
    return all(qary_channel_rho_sq(q, a, m) == target for q in alphabets)


if __name__ == "__main__":
    for m in range(0, 8):
        assert verify_alphabet_universality(F(3, 2), m)
    print("alphabet universality verified exactly for m = 0..7")

"""Algorithm C: pooled inverse-bit-length fit and band-crossing localisation."""

from __future__ import annotations

from fractions import Fraction as F
from typing import Dict, List, Optional, Sequence, Tuple


def rung_invariants(ladder: Dict[int, F]) -> Dict[int, F]:
    """The invariant I(b) = rho^2 * b, which is constant under any inverse-bit-length law."""
    return {b: r ** 2 * b for b, r in ladder.items()}


def select_inliers(ladder: Dict[int, F], lo: F, hi: F) -> List[int]:
    """Rungs whose invariant lies in the acceptance window [lo, hi]."""
    inv = rung_invariants(ladder)
    return [b for b in sorted(ladder) if lo <= inv[b] <= hi]


def pooled_constant(ladder: Dict[int, F], rungs: Sequence[int]) -> F:
    """Exact mean of the rung invariants over the selected rungs."""
    inv = rung_invariants(ladder)
    return sum((inv[b] for b in rungs), F(0)) / len(rungs)


def crossing_bitlen(pooled_C: F, floor: F) -> F:
    """The bit-length at which the fitted law C/b meets the squared acceptance floor."""
    return pooled_C / floor ** 2


def first_missing_rung(ladder: Dict[int, F], b_star: F) -> Optional[int]:
    """The least recorded rung strictly beyond the crossing: the predicted first band miss."""
    for b in sorted(ladder):
        if F(b) > b_star:
            return b
    return None


def one_step_ahead(ladder: Dict[int, F], rungs: Sequence[int]) -> List[Tuple[int, int, F, F]]:
    """Out-of-sample forecasts: fit the invariant at one rung, predict rho^2 at the next."""
    inv = rung_invariants(ladder)
    out: List[Tuple[int, int, F, F]] = []
    for lo, hi in zip(rungs, rungs[1:]):
        pred = inv[lo] / hi
        out.append((lo, hi, pred, abs(pred - ladder[hi] ** 2)))
    return out


if __name__ == "__main__":
    LADDER = {44: F(78, 100), 52: F(81, 100), 56: F(69, 100), 64: F(65, 100),
              68: F(61, 100), 72: F(61, 100), 76: F(61, 100), 80: F(57, 100),
              84: F(56, 100), 88: F(534, 1000)}
    inliers = select_inliers(LADDER, F(25), F(283, 10))
    C = pooled_constant(LADDER, inliers)
    b_star = crossing_bitlen(C, F(55, 100))
    print("inlier rungs        :", inliers)
    print("pooled constant C   :", C, "=", float(C))
    print("crossing bit-length :", float(b_star))
    print("first band miss at  :", first_missing_rung(LADDER, b_star))
    for lo, hi, pred, err in one_step_ahead(LADDER, inliers):
        print(f"  {lo} -> {hi}: predicted {float(pred):.4f}, error {float(err):.4f}")
